/**
 * fit-51 (S0b, P-PACK): `exports`, `main` and `bin` in package.json stay byte-identical to
 * test/fitness/entry-points-baseline.json for the whole layout migration (Q2's binding
 * condition). fit-14 still pins the tarball file list, which move slices regenerate; this
 * baseline is never regenerated by a move.
 */
import { describe, it, expect } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = new URL("../../", import.meta.url).pathname;
const read = (path: string): Record<string, unknown> => JSON.parse(readFileSync(join(ROOT, path), "utf-8"));

describe("fit-51 — P-PACK: exports, main and bin are unchanged", () => {
  const pkg = read("package.json");
  const baseline = read("test/fitness/entry-points-baseline.json");

  it("the baseline covers every public subpath, main and the codegen bin (non-vacuous)", () => {
    expect(Object.keys(baseline.exports as object).length).toBe(11);
    expect(baseline.main).toBe("./dist/index.js");
    expect(Object.keys(baseline.bin as object)).toEqual(["pbuilder-codegen"]);
  });

  it("package.json exports, main and bin serialize byte-identical to the baseline", () => {
    const pick = (o: Record<string, unknown>): string => JSON.stringify({ exports: o.exports, main: o.main, bin: o.bin }, null, 2);
    expect(pick(pkg)).toEqual(pick(baseline));
  });
});
